package android.os;import java.util.*;public class Binder implements IBinder{public static int caller=1000;public boolean alive=true;public final List<DeathRecipient> deaths=new ArrayList<>();public static int getCallingUid(){return caller;}protected void attachInterface(Object a,String s){}protected boolean onTransact(int c,Parcel d,Parcel r,int f)throws RemoteException{return false;}public boolean transact(int c,Parcel d,Parcel r,int f)throws RemoteException{return onTransact(c,d,r,f);}public boolean isBinderAlive(){return alive;}public void linkToDeath(DeathRecipient d,int f){deaths.add(d);}public boolean unlinkToDeath(DeathRecipient d,int f){return deaths.remove(d);}public void die(){alive=false;for(DeathRecipient d:new ArrayList<>(deaths))d.binderDied();}}